# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def make_student(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make_student("Thistle", "Bram", "B", "b@x"),
                make_student("Quillon", "Ada", "A", "a@x")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Quillon, Ada   A  a@x",
                "Thistle, Bram  B  b@x"
            ]
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows(
                [make_student("Thistle", "Bram", "B", None)]
            )
        message = str(caught.exception)
        self.assertIn("Thistle, Bram", message)

    def test_blank_email_is_missing(self):
        with self.assertRaises(ValueError):
            contact_rows(
                [make_student("Thistle", "Bram", "B", "  ")]
            )

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])
